import { test, expect } from '@playwright/test';

test.describe('Dropdown Escape Key Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <div>
        <button id="dropdown-trigger" aria-haspopup="true" aria-expanded="false">
          Options Menu
        </button>
        <div id="dropdown-menu" role="menu" style="display: none; position: absolute; background: white; border: 1px solid #ccc; min-width: 200px;">
          <button role="menuitem">Edit</button>
          <button role="menuitem">Delete</button>
          <button role="menuitem">Share</button>
        </div>
      </div>
      <script>
        const trigger = document.getElementById('dropdown-trigger');
        const menu = document.getElementById('dropdown-menu');

        trigger.addEventListener('click', () => {
          const isExpanded = trigger.getAttribute('aria-expanded') === 'true';
          trigger.setAttribute('aria-expanded', !isExpanded);
          menu.style.display = isExpanded ? 'none' : 'block';
        });

        document.addEventListener('keydown', (e) => {
          if (e.key === 'Escape' && menu.style.display === 'block') {
            trigger.setAttribute('aria-expanded', 'false');
            menu.style.display = 'none';
            trigger.focus();
          }
        });
      </script>
    `);
  });

  test('should close dropdown when Escape key is pressed', async ({ page }) => {
    const trigger = page.getByRole('button', { name: 'Options Menu' });
    const menu = page.getByRole('menu');

    // Open the dropdown
    await trigger.click();

    // Verify dropdown is open
    await expect(trigger).toHaveAttribute('aria-expanded', 'true');
    await expect(menu).toBeVisible();

    // Press Escape key
    await page.keyboard.press('Escape');

    // Verify dropdown is closed
    await expect(trigger).toHaveAttribute('aria-expanded', 'false');
    await expect(menu).not.toBeVisible();
  });

  test('should return focus to trigger button after closing with Escape', async ({ page }) => {
    const trigger = page.getByRole('button', { name: 'Options Menu' });
    const editOption = page.getByRole('menuitem', { name: 'Edit' });

    // Open the dropdown
    await trigger.click();
    await expect(trigger).toHaveAttribute('aria-expanded', 'true');

    // Focus on a menu item
    await editOption.focus();

    // Press Escape key
    await page.keyboard.press('Escape');

    // Verify focus returns to trigger button
    await expect(trigger).toBeFocused();
  });

  test('should not close dropdown when Escape is pressed while menu is closed', async ({ page }) => {
    const trigger = page.getByRole('button', { name: 'Options Menu' });
    const menu = page.getByRole('menu');

    // Ensure dropdown is closed
    await expect(trigger).toHaveAttribute('aria-expanded', 'false');

    // Press Escape key
    await page.keyboard.press('Escape');

    // Verify dropdown remains closed
    await expect(trigger).toHaveAttribute('aria-expanded', 'false');
    await expect(menu).not.toBeVisible();
  });

  test('should allow keyboard navigation within dropdown before closing with Escape', async ({ page }) => {
    const trigger = page.getByRole('button', { name: 'Options Menu' });
    const deleteOption = page.getByRole('menuitem', { name: 'Delete' });

    // Open the dropdown
    await trigger.click();
    await expect(trigger).toHaveAttribute('aria-expanded', 'true');

    // Navigate to Delete option
    await deleteOption.focus();
    await expect(deleteOption).toBeFocused();

    // Press Escape to close
    await page.keyboard.press('Escape');

    // Verify dropdown is closed and focus returns to trigger
    await expect(trigger).toHaveAttribute('aria-expanded', 'false');
    await expect(trigger).toBeFocused();
  });
});
